  "root_causes": [
    {
      "service": "ts-order-service",
      "fault_kind": "process_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'ab' p, metric, round(avg(value),3) avgv, round(max(value),3) maxv FROM abnormal_metrics WHERE service_name='ts-order-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2 UNION ALL SELECT 'no', metric, round(avg(value),3), round(max(value),3) FROM normal_metrics WHERE service_name='ts-order-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2",
          "claim": "ts-order-service pod CPU averaged 1.54 cores with a 23.4 peak, against 0.18 normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'ab' p, metric, round(max(value),1) maxv, round(avg(value),1) avgv FROM abnormal_metrics_sum WHERE service_name='ts-order-service' AND metric='jvm.cpu.time' GROUP BY 1,2 UNION ALL SELECT 'no', metric, round(max(value),1), round(avg(value),1) FROM normal_metrics_sum WHERE service_name='ts-order-service' AND metric='jvm.cpu.time' GROUP BY 1,2",
          "claim": "Order-service JVM cumulative CPU time rose to about 367 s in the incident, against about 13 s normal; heap and GC metrics stayed normal.",
          "_note": "avg/max of cumulative jvm.cpu.time"
        },
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND span_name IN ('SELECT Order','SELECT ts.orders','OrderRepository.findByAccountId') GROUP BY 1,2 UNION ALL SELECT 'no', span_name, count(*), round(avg(duration)/1e6,1), round(max(duration)/1e6,1) FROM normal_traces WHERE service_name='ts-order-service' AND span_name IN ('SELECT Order','SELECT ts.orders','OrderRepository.findByAccountId') GROUP BY 1,2",
          "claim": "Order ORM 'SELECT Order' averages 96 ms vs 2.6 ms normal, while the JDBC 'SELECT ts.orders' stays about 1.5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND span_name='POST /api/v1/orderservice/order/refresh' UNION ALL SELECT 'no', count(*), round(avg(duration)/1e6,1) FROM normal_traces WHERE service_name='ts-order-service' AND span_name='POST /api/v1/orderservice/order/refresh'",
          "claim": "Order refresh endpoint averages 575 ms in the incident against 12 ms normal, with individual calls reaching 90 s."
        }
      ]
    },
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_slow",
